const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function duration(seconds){if(seconds===null||seconds===undefined)return '—';const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=seconds%60;return `${h?`${h}:`:''}${String(m).padStart(h?2:1,'0')}:${s.toFixed(1).padStart(4,'0')}`}
function riderLaps(rider){return rider.laps.map(lap=>`<span class="lap-chip">#${lap.number} · ${esc(lap.finish)}${lap.time!==null?` (${duration(lap.time)})`:''}</span>`).join('')||'—'}
async function renderTeams(){const root=document.querySelector('#team-results');try{const response=await fetch('/api/public/team-race',{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json();if(!data.teams.some(team=>team.laps)){root.innerHTML='<div class="empty">Waiting for the first Base finish read.</div>';return}const riders=data.teams.flatMap(team=>team.members.map(member=>({...member,team:team.name}))).sort((a,b)=>b.lap_count-a.lap_count||a.name.localeCompare(b.name));root.innerHTML=`<section class="race-grid single"><article class="race-table"><header><div><span>Live standings</span><h3>Team totals</h3></div><b>Start ${esc(data.start)}</b></header><div class="table-scroll"><table><thead><tr><th>Pos</th><th>Team</th><th>Laps</th><th>Reached total</th><th>Fastest lap</th></tr></thead><tbody>${data.teams.map((team,index)=>`<tr class="${index<3?'podium':''}"><td class="place">${index+1}</td><td><strong>${esc(team.name)}</strong></td><td class="time">${team.laps}</td><td class="time">${duration(team.completion)}</td><td class="time">${duration(team.fastest)}</td></tr>`).join('')}</tbody></table></div></article></section><section class="result-card team-rider-results"><div class="history-heading"><div><span>Individual laps</span><h2>Every rider’s Base finishes</h2></div></div><div class="table-scroll"><table><thead><tr><th>Rider</th><th>Team</th><th>Personal laps</th><th>Fastest</th><th>All laps</th></tr></thead><tbody>${riders.map(rider=>`<tr><td><a class="rider" href="/rider/?event=team&bib=${encodeURIComponent(rider.bib)}"><span class="bib">${esc(rider.bib)}</span><strong>${esc(rider.name)}</strong></a></td><td>${esc(rider.team)}</td><td class="time">${rider.lap_count}</td><td class="time">${duration(rider.fastest)}</td><td class="lap-list">${riderLaps(rider)}</td></tr>`).join('')}</tbody></table></div></section>`}catch{root.innerHTML='<div class="empty">Waiting for team timing data.</div>'}}
renderTeams();setInterval(renderTeams,15000);
